gen-control.c:script:
const valueProp = dispMeta?.id || 'docStatus';
const labelProp = propMeta?.['graphql:labelProp'] || (valueProp + '_label');
return {
    cell: { type: "text", text: '<span class="label label-${' + valueProp
        + " == 'ACTIVE' ? 'primary' : 'default'}\" "
        + "${" + valueProp
        + " == 'CANCELLED' ? \"style='text-decoration:line-through'\" : ''}>"
        + "${" + labelProp + "}</span>" }
};

return {
    type: 'container', direction: 'column', gap: 'sm',
    body: [
        {
            type: 'data-source', name: 'previewData', action: 'ajax',
            args: { url: '@query:ErpFinReconciliation__previewReverse', method: 'post', data: { reconciliationId: '${id}' } }
        },
        {
            type: 'text',
            text: "核销单号：<b>${previewData.code}</b>（${previewData.direction}）<br/>核销总额(本位币)：${previewData.totalAmountFunctional}<br/>将回退 ${(previewData.revertedItems ?? []).length} 项 AR/AP 辅助账（SETTLED→OPEN/PARTIAL），并刷新往来单位余额。<br/><span style='color:#8a6d3b'>注意：核销冲销不生成红字凭证（凭证由收付款审核时生成）。</span><br/>确认后核销单状态将置为「已冲销」，不可恢复。"
        },
        {
            type: 'button', label: '确认冲销', level: 'danger',
            onClick: {
                action: 'ajax',
                args: { url: '@mutation:ErpFinReconciliation__reverse?reconciliationId=${id}', method: 'post' },
                messages: { success: '核销单已冲销' },
                then: [ { action: 'closeSurface' }, { action: 'refreshNearest' } ]
            }
        }
    ]
};
